def _dst(y, mo, d):
    import datetime as _dt
    m1 = _dt.date(y, 3, 1)
    ms = 1 + ((6 - m1.weekday()) % 7) + 7
    n1 = _dt.date(y, 11, 1)
    ne = 1 + ((6 - n1.weekday()) % 7)
    if mo < 3 or mo > 11:
        return False
    if 3 < mo < 11:
        return True
    if mo == 3:
        return d >= ms
    return d < ne


def _et_minutes(bars):
    """Minute-of-day in America/New_York for every bar. UTC in, ET out."""
    off = {}
    out = []
    for b in bars:
        ts = str(b["t"])
        day = ts[:10]
        o = off.get(day)
        if o is None:
            o = -4 if _dst(int(ts[0:4]), int(ts[5:7]), int(ts[8:10])) else -5
            off[day] = o
        out.append((int(ts[11:13]) + o) * 60 + int(ts[14:16]))
    return out


def family_init(ctx):
    import math
    bars = ctx.bars
    n = len(bars)
    c = [float(b["c"]) for b in bars]
    et = _et_minutes(bars)
    day = [str(b["t"])[:10] for b in bars]
    ctx.et = et

    # 5-minute log returns, never across the overnight gap
    r = [0.0] * n
    for j in range(1, n):
        if day[j] != day[j - 1]:
            continue
        if c[j - 1] > 0 and c[j] > 0:
            r[j] = math.log(c[j] / c[j - 1])

    k = float(ctx.p.jump_k)
    w0, w1 = int(ctx.p.win_start), int(ctx.p.win_end)
    emin = int(ctx.p.entry_min)
    md = int(ctx.p.med_days)
    first = int(ctx.p.use_first)

    # bar indices grouped by session, in order
    groups = []
    cur = []
    for j in range(n):
        if j and day[j] != day[j - 1]:
            groups.append(cur)
            cur = []
        cur.append(j)
    if cur:
        groups.append(cur)

    sig = [0] * n
    hist = []                      # per-session lists of |5-min return|
    for g in groups:
        # ---- the scale: median |return| over the trailing sessions ----
        use = hist[-md:] if len(hist) >= md else hist
        m = None
        if len(use) >= 3:
            pool = []
            for hh in use:
                pool.extend(hh)
            pool = [x for x in pool if x > 0]
            if len(pool) >= 20:
                pool.sort()
                q = len(pool) // 2
                m = pool[q] if len(pool) % 2 else 0.5 * (pool[q - 1] + pool[q])

        todays = [abs(r[j]) for j in g if abs(r[j]) > 0]

        if m is not None and m > 0:
            thr = k * m
            jumps = [(j, r[j]) for j in g
                     if w0 <= et[j] <= w1 and abs(r[j]) >= thr]
            d = 0
            if jumps:
                if first:
                    d = 1 if jumps[0][1] > 0 else -1
                    for j, x in jumps[1:]:
                        if (1 if x > 0 else -1) != d:
                            d = 0          # a reversal cancels the session
                            break
                else:
                    big = max(jumps, key=lambda p: abs(p[1]))
                    d = 1 if big[1] > 0 else -1
            if d:
                for j in g:
                    if et[j] >= emin:
                        sig[j] = d
                        break

        hist.append(todays)

    ctx.sg = sig


def signal(ctx, i):
    return ctx.sg[i]


def exit_signal(ctx, i):
    return ctx.et[i] >= int(ctx.p.exit_min)
